import { LDProvider } from '@launchdarkly/react-native-client-sdk'
import { launchDarklyClient } from './launchDarklyClient'
import { useMeLazyQuery } from '@/generated/graphql'
import { useEffect } from 'react'
import { useAuthStore } from '@/stores'
export const LaunchDarklyProvider = ({
	children
}: {
	children: React.ReactNode
}) => {
	const { isReady, auth } = useAuthStore()

	const [getMe] = useMeLazyQuery()

	useEffect(() => {
		if (isReady) {
			if (auth) {
				getMe().then(({ data }) => {
					if (data?.me) {
						launchDarklyClient.identify({
							kind: 'multi',
							user: { key: data.me.id, email: data.me.email }
						})
					}
				})
			} else {
				launchDarklyClient.identify({
					kind: 'multi',
					user: { key: 'anonymous' }
				})
			}
		}
	}, [isReady, auth])

	return <LDProvider client={launchDarklyClient}>{children}</LDProvider>
}
